from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")  # Step 1: Remove any spaces from the input string
    result = []
    stack = []
    start = 0

    for i, char in enumerate(paren_string):
        if char == '(':
            stack.append(i)
        elif char == ')':
            if stack:
                start = stack.pop()
                group = paren_string[start:i+1]
                if group.count('(') == group.count(')'):  # Step 3: Check if each group is balanced
                    result.append(group)

    return result  # Step 5: Return the list of separate strings

